import{_ as a,o as t,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const d=JSON.parse('{"title":"Partenariats technologiques","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/activites/partenariats.md","filePath":"src/guide/activites/partenariats.md"}'),i={name:"guide/activites/partenariats.md"};function s(o,e,l,u,g,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="partenariats-technologiques" tabindex="-1">Partenariats technologiques <a class="header-anchor" href="#partenariats-technologiques" aria-label="Permalink to &quot;Partenariats technologiques&quot;">​</a></h1><p>Un partenariat technologique intègre l&#39;outil, la plateforme ou la certification d&#39;une organisation dans un ou plusieurs programmes. Il est <strong>gratuit</strong>, en échange d&#39;une <strong>visibilité</strong> auprès des apprenants.</p><p>Le <strong>Chargé de partenariats</strong> et l&#39;Administrateur les gèrent, dans <strong>Activités → Partenariats technologiques</strong>.</p><h2 id="creer-un-partenariat" tabindex="-1">Créer un partenariat <a class="header-anchor" href="#creer-un-partenariat" aria-label="Permalink to &quot;Créer un partenariat&quot;">​</a></h2><p><strong>Nouveau partenariat</strong> : le partenariat naît <strong>En négociation</strong>. Indiquez :</p><ul><li>l&#39;<strong>organisation partenaire</strong> et le <strong>nom de la solution</strong> ;</li><li>la <strong>nature</strong> : intégration pédagogique, certification ou fourniture d&#39;outils ;</li><li>les <strong>référentiels concernés</strong> (au moins un) ;</li><li>le <strong>signataire</strong> du partenaire, avec son nom et son e-mail ;</li><li>la <strong>fin prévue</strong>, facultative.</li></ul><p>Un partenariat se modifie, ou se supprime, <strong>jusqu&#39;à sa signature</strong>. Modifier un partenariat dont le contrat est déjà envoyé retire cet envoi : il faut renvoyer le contrat.</p><h2 id="faire-signer-le-contrat" tabindex="-1">Faire signer le contrat <a class="header-anchor" href="#faire-signer-le-contrat" aria-label="Permalink to &quot;Faire signer le contrat&quot;">​</a></h2><p><strong>Envoyer le contrat</strong> adresse au signataire un lien par e-mail, valable <strong>7 jours</strong>. Il lit le contrat jusqu&#39;au bout, l&#39;accepte au nom de son organisation et le signe avec un <strong>code</strong> reçu à la même adresse, <strong>sans compte Kura</strong>. <strong>Renvoyer le contrat</strong> émet un nouveau lien.</p><p>Ensuite, edPage group <strong>contre-signe</strong> : automatiquement (par défaut) ou, selon le réglage de l&#39;Administrateur, par un Chargé de partenariats avec <strong>Contre-signer</strong>.</p><p>À la contre-signature, le contrat reçoit sa référence <code>CONVP-NB-AAAA-XXX</code> et son PDF scellé, envoyé au contact et aux Chargés. Le partenariat devient <strong>Actif</strong> : le partenaire, la solution, la nature et les référentiels sont alors <strong>figés</strong>.</p><h2 id="la-visibilite" tabindex="-1">La visibilité <a class="header-anchor" href="#la-visibilite" aria-label="Permalink to &quot;La visibilité&quot;">​</a></h2><p>La <strong>visibilité</strong> du partenariat reste modifiable : une présentation (500 caractères au plus), le site du partenaire, un logo (PNG, JPEG ou WebP, 1 Mo au plus). Un aperçu est affiché.</p><p>Un partenariat actif apparaît :</p><ul><li>sur la page de <strong>chacun de ses référentiels</strong> sur le site NextBoxx ;</li><li>dans un bloc « <strong>Partenaires</strong> » du résumé du cours Sève des cohortes concernées, mis à jour chaque heure ;</li><li>pour les apprenants, sous <strong>Outils partenaires</strong> dans leur espace.</li></ul><h2 id="la-fin-d-un-partenariat" tabindex="-1">La fin d&#39;un partenariat <a class="header-anchor" href="#la-fin-d-un-partenariat" aria-label="Permalink to &quot;La fin d&#39;un partenariat&quot;">​</a></h2><p>Le partenariat <strong>prend fin le lendemain de sa date de fin</strong>, fixée à la création ou plus tard. Il passe <strong>Terminé</strong> et le site ne l&#39;affiche plus.</p><p>Une cohorte d&#39;un référentiel concerné <strong>garde le partenaire jusqu&#39;à sa propre fin</strong>, dans Sève et dans l&#39;espace des apprenants, si elle a commencé, ou si l&#39;une de ses inscriptions a été signée, au plus tard à la date de fin du partenariat.</p>',18)])])}const f=a(i,[["render",s]]);export{d as __pageData,f as default};
